const form=document.querySelector('#enquiry-form');
const checkin=form.elements.checkin,checkout=form.elements.checkout;
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function nextDate(value){const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+1);return localDate(d)}
checkin.min=localDate(new Date());checkout.min=nextDate(checkin.min);
checkin.addEventListener('change',()=>{checkout.min=checkin.value?nextDate(checkin.value):nextDate(checkin.min);checkout.setCustomValidity('');if(checkout.value&&checkout.value<checkout.min)checkout.value='';});
checkout.addEventListener('input',()=>checkout.setCustomValidity(''));
document.querySelector('#menu').addEventListener('click',e=>{const open=document.querySelector('#nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false')}));
document.querySelectorAll('.room-enquire').forEach(button=>button.addEventListener('click',()=>{form.elements.room.value=button.dataset.room;document.querySelector('#enquire').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});form.elements.room.focus({preventScroll:true});}));
const dialog=document.querySelector('#enquiry-dialog');
let message='';
const readable=value=>new Date(value+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
form.addEventListener('submit',e=>{e.preventDefault();document.querySelector('#form-error').textContent='';const data=Object.fromEntries(new FormData(form));if(!data.name.trim()){document.querySelector('#form-error').textContent='Please enter your name.';form.elements.name.focus();return}if(data.checkin<localDate(new Date())||data.checkout<=data.checkin){document.querySelector('#form-error').textContent='Choose a future stay, with check-out after check-in.';return}const nights=Math.round((Date.parse(data.checkout+'T12:00:00')-Date.parse(data.checkin+'T12:00:00'))/86400000);message=`Hello Necila, I would like to enquire about a stay at Palacete Rodrigues.\n\nName: ${data.name.trim()}\nEmail: ${data.email.trim()}\nCheck-in: ${readable(data.checkin)}\nCheck-out: ${readable(data.checkout)}\nNights: ${nights}\nAdults: ${data.adults}\nChildren: ${data.children}\nRoom preference: ${data.room}${data.notes.trim()?'\nAdditional details: '+data.notes.trim():''}\n\nPlease let me know the availability, total rate and booking terms. Thank you!`;document.querySelector('#message-preview').textContent=message;document.querySelector('#whatsapp-send').href='https://wa.me/919422056467?text='+encodeURIComponent(message);document.querySelector('#email-send').href='mailto:info@palacetegoa.com?subject='+encodeURIComponent('Stay enquiry | '+readable(data.checkin)+' | '+data.name.trim())+'&body='+encodeURIComponent(message);document.querySelector('#copy-status').textContent='';dialog.showModal();});
document.querySelector('#copy-message').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(message);document.querySelector('#copy-status').textContent='Message copied. Paste it into WhatsApp or email.'}catch{document.querySelector('#copy-status').textContent='Copy is unavailable here. Select the message above and copy it manually.'}});
document.querySelector('#sources-open').addEventListener('click',()=>document.querySelector('#sources-dialog').showModal());
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
